package ama.transcript;
import ama.contract.IdentityContracts.Actor;import ama.contract.TaskContracts.SubjectRef;import java.util.*;
/** Header-only explicit disposition. It cannot acquire content-copy authority. */
public final class JdbcMinutesDecisions {
 private final JdbcTranscriptAuthority authority;private final JdbcMinutesCommandReceipts receipts;
 public JdbcMinutesDecisions(JdbcTranscriptAuthority authority){this.authority=Objects.requireNonNull(authority);receipts=new JdbcMinutesCommandReceipts(authority.dataSource(),authority.transactionRunner(),authority.savedAccess());}
 public Map<String,Object> reject(Actor actor,String meeting,String key,long expected,String candidate,String trace){return decide(actor,meeting,key,expected,candidate,trace,false);}
 public Map<String,Object> dispose(Actor actor,String meeting,String key,long expected,String candidate,String trace){return decide(actor,meeting,key,expected,candidate,trace,true);}
 private Map<String,Object> decide(Actor actor,String meeting,String key,long expected,String candidate,String trace,boolean disposal){JdbcMinutesFactsReader.independent();ama.contract.MinutesContracts.uuid(candidate);ama.contract.MinutesContracts.uuid(trace);String operation=disposal?"MINUTES_DISPOSE":"MINUTES_REJECT";var identity=JdbcMinutesCommandReceipts.identity(actor,meeting,operation,key,expected,candidate);var replay=receipts.lookup(actor,meeting,identity);if(replay.isPresent())return replay.orElseThrow();Object prepared=null;RuntimeException error=null;try{prepared=authority.prepareMinutesDecision(actor,meeting,candidate,expected,disposal);}catch(RuntimeException failure){if(Thread.currentThread().isInterrupted()||failure instanceof ama.contract.MinutesContracts.Failure f&&f.code()==ama.contract.MinutesContracts.FailureCode.CANCELLED)throw failure;error=failure;}final var plan=prepared;final var failed=error;
  return authority.transactionRunner().required(()->{var stored=receipts.claim(actor,meeting,identity);var gate=authority.fileRegistry().lock(actor,meeting,ama.access.MeetingAccess.Action.EDIT);JdbcMinutesCommandReceipts.match(stored);if(stored.result()!=null)return receipts.restore(meeting,identity,stored,true);if(failed!=null)throw failed;var scope=authority.captureMinutesDecision(plan,gate,actor,meeting);authority.writeMinutesDecision(scope,plan,gate);receipts.accepted(identity,candidate);var response=receipts.restore(meeting,identity,new JdbcMinutesCommandReceipts.Stored(candidate,200,true),false);String event=disposal?"MINUTES_CANDIDATE_DISPOSED":"MINUTES_CANDIDATE_REJECTED";new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(actor.enterpriseId(),event,meeting,expected+1,"SUCCEEDED",trace,java.time.Instant.now()));var outbox=new ama.task.JdbcOutbox(authority.dataSource(),new MinutesEventReferences(authority.dataSource()).validators());outbox.append(new ama.contract.OutboxContracts.EventDraft(event,null,new SubjectRef("MEETING",meeting),expected+1,new ama.contract.OutboxContracts.Reference("GENERATION_CANDIDATE",candidate)));outbox.flush();return response;});}
}
